	private void TaskScheduler_UnobservedTaskException(object sender, UnobservedTaskExceptionEventArgs e)
	{
		LogHelper.Error("Task异常：", e.Exception);
		e.SetObserved();
	}

	[MethodImpl(MethodImplOptions.NoInlining)]
	private static void InitializeCefSharp()
	{
		CefSettings cefSettings = new CefSettings();
		cefSettings.CefCommandLineArgs.Add("--disable-web-security", "1");
		cefSettings.CefCommandLineArgs.Add("--enable-system-flash", "1");
		cefSettings.CefCommandLineArgs.Add("--disable-application-cache", "false");
		cefSettings.CefCommandLineArgs.Add("--disable-session-storage", "false");
		cefSettings.CefCommandLineArgs.Add("--disk-cache-size", "104857600");
		cefSettings.RootCachePath = AppDomain.CurrentDomain.BaseDirectory + "/cache";
		CefSharpSettings.ShutdownOnExit = true;
		Cef.EnableHighDPISupport();
		cefSettings.Locale = "zh-CN";
		cefSettings.UserAgent = CreateUserAgent();
		cefSettings.BrowserSubprocessPath = Path.Combine(AppDomain.CurrentDomain.SetupInformation.ApplicationBase, Environment.Is64BitProcess ? "x64" : "x86", "CefSharp.BrowserSubprocess.exe");
		Cef.Initialize((CefSettingsBase)cefSettings, performDependencyCheck: false, (IBrowserProcessHandler)null);
	}

	private static Assembly Resolver(object sender, ResolveEventArgs args)
	{
		if (args.Name.StartsWith("CefSharp"))
		{
			string path = args.Name.Split(new char[1] { ',' }, 2)[0] + ".dll";
			string path2 = Path.Combine(AppDomain.CurrentDomain.SetupInformation.ApplicationBase, Environment.Is64BitProcess ? "x64" : "x86", path);
			return File.Exists(path2) ? Assembly.LoadFile(path2) : null;
		}
		return null;
	}

	public void ReleaseResourceToDisk(string resourceFileName, string targetPath)
	{
		string text = Assembly.GetExecutingAssembly().GetName().Name + ".Resources." + resourceFileName;
		Assembly executingAssembly = Assembly.GetExecutingAssembly();
		using Stream stream = executingAssembly.GetManifestResourceStream(text);
		if (stream == null)
		{
			throw new FileNotFoundException("资源文件未找到", text);
		}
		using FileStream destination = new FileStream(targetPath, FileMode.Create, FileAccess.Write);
		stream.CopyTo(destination);
	}

	private static string CreateUserAgent()
	{
		Random random = new Random();
		int num = random.Next(88, 130);
		int num2 = random.Next(0, 10);
		int num3 = random.Next(0, 10000);
		int num4 = random.Next(0, 200);
		string text = $"{num}.{num2}.{num3}.{num4}";
		return "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/" + text + " Safari/537.36";
	}


